#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;if(!(cin>>n>>m))return 0;vector<vector<pair<int,long long>>>g(n+1);for(int i=0,u,v;i<m;i++){long long w;cin>>u>>v>>w;g[u].push_back({v,w});g[v].push_back({u,w});}const long long INF=LLONG_MAX/4;vector<long long>d(n+1,INF);vector<char>used(n+1);priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>>q;d[1]=0;q.push({0,1});long long ans=0;int cnt=0;while(!q.empty()){auto [w,u]=q.top();q.pop();if(used[u]||w!=d[u])continue;used[u]=1;ans+=w;cnt++;for(auto [v,x]:g[u])if(!used[v]&&x<d[v]){d[v]=x;q.push({x,v});}}cout<<ans<<endl;return 0;}